<?php

namespace App\Helpers;

class MenuHelper
{
    /**
     * @return array<int, array{icon: string, name: string, path: string}>
     */
    public static function getMainNavItems(): array
    {
        return [
            [
                'icon' => 'dashboard',
                'name' => __('ui.nav.dashboard'),
                'path' => '/dashboard',
            ],
            [
                'icon' => 'calendar',
                'name' => __('ui.nav.events'),
                'path' => '/events',
            ],
            [
                'icon' => 'chat',
                'name' => __('ui.nav.forum'),
                'path' => '/forum',
            ],
            [
                'icon' => 'pages',
                'name' => __('ui.nav.programs'),
                'path' => '/programs',
            ],
        ];
    }

    /**
     * @return array<int, array{icon: string, name: string, path: string}>
     */
    public static function getSettingsNavItems(): array
    {
        return [
            [
                'icon' => 'user-profile',
                'name' => __('ui.nav.profile'),
                'path' => '/profile',
            ],
            [
                'icon' => 'settings',
                'name' => __('ui.nav.app_settings'),
                'path' => '/settings',
            ],
        ];
    }

    /**
     * @return array<int, array<string, string>>
     */
    public static function getSupportItems(): array
    {
        return [];
    }

    /**
     * @return array<int, array{title: string, items: array<int, array{icon: string, name: string, path: string}>}>
     */
    public static function getMenuGroups(): array
    {
        return [
            [
                'title' => __('ui.nav.menu'),
                'items' => self::getMainNavItems(),
            ],
            [
                'title' => __('ui.nav.settings'),
                'items' => self::getSettingsNavItems(),
            ],
        ];
    }

    public static function isActive(string $path): bool
    {
        return request()->is(ltrim($path, '/'));
    }

